function loadUser(id, cb) {
  fetch('/api/users/' + id).then(function (r) {
    if (!r.ok) { cb(new Error('bad status ' + r.status)); return; }
    r.json().then(function (u) {
      fetch('/api/orgs/' + u.orgId).then(function (r2) {
        r2.json().then(function (o) { u.org = o; cb(null, u); });
      }).catch(function (e) { cb(e); });
    });
  }).catch(function (e) { cb(e); });
}
function loadUsers(ids, cb) {
  var out = []; var left = ids.length;
  ids.forEach(function (id, i) {
    loadUser(id, function (err, u) {
      if (err) { cb(err); return; }
      out[i] = u; left--; if (left === 0) cb(null, out);
    });
  });
}
module.exports = { loadUser, loadUsers };
